import{b as o,O as e,g as a,j as d}from"./chunks/framework.DcaUmd3X.js";const g=JSON.parse('{"title":"代码检查与走查","description":"","frontmatter":{},"headers":[],"relativePath":"testing/basics/code-review/index.md","filePath":"测试理论与实践/1.测试基础认知/03.代码检查与走查.md","lastUpdated":1781625968000}'),l={name:"testing/basics/code-review/index.md"};function r(i,t,n,s,c,h){return e(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="代码检查与走查" tabindex="-1">代码检查与走查 <a class="header-anchor" href="#代码检查与走查" aria-label="Permalink to &quot;代码检查与走查&quot;">​</a></h1><blockquote><p>在代码跑起来之前，用一双&quot;错别字侦探&quot;的眼睛扫描源码，就能发现大量 bug——这是成本最低的找错方式。</p></blockquote><h2 id="为什么代码检查值得做" tabindex="-1">为什么代码检查值得做 <a class="header-anchor" href="#为什么代码检查值得做" aria-label="Permalink to &quot;为什么代码检查值得做&quot;">​</a></h2><p>很多人觉得&quot;代码是给机器跑的，人看有什么用&quot;。但大量实践证明：<strong>代码检查发现的 bug 数量，往往比实际运行测试发现的还多</strong>。</p><p>原因很简单：</p><ul><li>机器运行测试只能告诉你&quot;结果对不对&quot;，但<strong>人看代码能发现&quot;逻辑对不对&quot;</strong></li><li>一个边界值问题，自动化测试可能跑 100 次才触发一次，但人看一眼 <code>if (i &gt; 10)</code> 就知道 <code>i == 10</code> 没处理</li><li>代码检查还能发现<strong>测试永远覆盖不到的 bug</strong>：比如某个变量声明了但从来没用、某个分支逻辑反了但恰好没有测试数据能触发</li></ul><p>当然，代码检查不是银弹——它<strong>不能替代运行测试</strong>，因为有些问题只能在实际执行中暴露（性能瓶颈、内存泄漏、并发竞态）。但它确实是在测试执行之前，性价比最高的一道防线。</p><h2 id="三种形式-检查、走查、评审" tabindex="-1">三种形式：检查、走查、评审 <a class="header-anchor" href="#三种形式-检查、走查、评审" aria-label="Permalink to &quot;三种形式：检查、走查、评审&quot;">​</a></h2><p>代码审查有三种渐进的形式：</p><table tabindex="0"><thead><tr><th>形式</th><th>谁来做</th><th>怎么做的</th><th>适合场景</th></tr></thead><tbody><tr><td><strong>代码检查（Inspection）</strong></td><td>3~5 人小会，含作者和非作者</td><td>对照错误清单逐项检查，有严格流程</td><td>关键模块、安全相关代码</td></tr><tr><td><strong>代码走查（Walkthrough）</strong></td><td>作者主导，1~3 人参与</td><td>作者逐行讲解代码逻辑，参与者提问</td><td>新功能的代码、需要知识传递时</td></tr><tr><td><strong>同行评审（Review）</strong></td><td>1 位评审者</td><td>评审者自行阅读代码，提交意见</td><td>日常小改动、快速审查</td></tr></tbody></table><p>三种形式不是互斥的。一个支付模块可以先走查（作者讲解业务逻辑），再检查（对照清单逐项排查），最后让另一个同事做快速评审。</p><h2 id="代码检查的错误清单" tabindex="-1">代码检查的错误清单 <a class="header-anchor" href="#代码检查的错误清单" aria-label="Permalink to &quot;代码检查的错误清单&quot;">​</a></h2><p>以下是一份经过大量实践验证的错误分类检查表。你不需要每次都全查，但<strong>至少要把这些条目在脑子里过一遍</strong>。</p><h3 id="一、数据引用错误" tabindex="-1">一、数据引用错误 <a class="header-anchor" href="#一、数据引用错误" aria-label="Permalink to &quot;一、数据引用错误&quot;">​</a></h3><p>跟&quot;变量用没用到、用到对不对&quot;相关：</p><ul><li>使用的变量有没有初始化？比如声明了 <code>int count;</code> 但没赋值就开始 <code>count++</code></li><li>下标是否越界？数组长度为 10，访问了 <code>arr[10]</code></li><li>指针或引用是否指向了已释放的内存？</li><li>多个线程同时读写同一个变量，有没有加锁？</li><li>变量类型不匹配——把 <code>long</code> 赋值给 <code>int</code>，大数字被截断</li></ul><h3 id="二、数据声明错误" tabindex="-1">二、数据声明错误 <a class="header-anchor" href="#二、数据声明错误" aria-label="Permalink to &quot;二、数据声明错误&quot;">​</a></h3><p>变量本身写对了吗：</p><ul><li>变量名跟另一个变量太像，容易写混——<code>userName</code> 和 <code>usreName</code></li><li>变量长度不够——用 <code>int</code> 存用户 ID，结果用户破了 21 亿</li><li>默认值跟预想的不一样——Java 的 <code>boolean</code> 默认是 <code>false</code>，但业务逻辑期望的是不传值时报错</li></ul><h3 id="三、运算错误" tabindex="-1">三、运算错误 <a class="header-anchor" href="#三、运算错误" aria-label="Permalink to &quot;三、运算错误&quot;">​</a></h3><p>计算过程出的问题：</p><ul><li>整数除法丢精度——<code>5 / 2</code> 结果是 <code>2</code> 而不是 <code>2.5</code></li><li>运算符优先级搞混——<code>a &amp;&amp; b || c</code> 到底该先算哪个</li><li>溢出——两个大整数相乘超出类型上限</li><li>不同精度的数据混算——<code>float</code> 和 <code>double</code> 混在一起，精度被悄悄地拉低</li><li>除零——分母可能是 0 的情况没判断</li></ul><h3 id="四、比较错误" tabindex="-1">四、比较错误 <a class="header-anchor" href="#四、比较错误" aria-label="Permalink to &quot;四、比较错误&quot;">​</a></h3><p>判断条件的坑：</p><ul><li>比较方向反了——<code>if (a &lt; b)</code> 写成了 <code>if (a &gt; b)</code></li><li><code>==</code> 写成了 <code>=</code>（C/C++ 里这是个经典 bug，赋值表达式返回赋值后的值，编译不报错）</li><li>浮点数直接 <code>==</code> 比较——<code>0.1 + 0.2 == 0.3</code> 是 <code>false</code></li><li>比较的两种类型不一致——字符串 <code>&quot;10&quot;</code> 和数字 <code>10</code> 的比较，不同语言行为不一样</li><li>逻辑条件写错——<code>a &amp;&amp; b</code> 写成了 <code>a || b</code></li></ul><h3 id="五、控制流程错误" tabindex="-1">五、控制流程错误 <a class="header-anchor" href="#五、控制流程错误" aria-label="Permalink to &quot;五、控制流程错误&quot;">​</a></h3><p>循环和分支的陷阱：</p><ul><li>无限循环——循环终止条件永远为真</li><li>循环多一次或少一次（off-by-one）——应该是 <code>&lt; n</code> 写成了 <code>&lt;= n</code></li><li><code>switch</code> 忘了写 <code>break</code></li><li>异常被吞了——<code>try { ... } catch (Exception e) { }</code>，出错了没有任何日志</li><li>嵌套太深，逻辑绕不出来了——如果一段代码有 5 层 <code>if</code> + 3 层 <code>for</code>，不如重写</li></ul><h3 id="六、接口错误" tabindex="-1">六、接口错误 <a class="header-anchor" href="#六、接口错误" aria-label="Permalink to &quot;六、接口错误&quot;">​</a></h3><p>模块之间传参数的问题：</p><ul><li>参数顺序搞错——<code>transfer(from, to, amount)</code> 调用时写成了 <code>transfer(to, from, amount)</code></li><li>参数单位不一致——一个函数期望传&quot;秒&quot;，调用方传了&quot;毫秒&quot;</li><li>返回值检查缺失——调用了一个可能返回 <code>null</code> 的函数，没判空直接用</li><li>全局变量被多个模块修改，谁都说不清当前值是什么</li></ul><h3 id="七、输入-输出错误" tabindex="-1">七、输入 / 输出错误 <a class="header-anchor" href="#七、输入-输出错误" aria-label="Permalink to &quot;七、输入 / 输出错误&quot;">​</a></h3><ul><li>读取文件时，文件不存在怎么办？</li><li>写入文件时，磁盘满了怎么处理？</li><li>网络请求超时了，有没有重试？重试了几次？</li></ul><h2 id="怎么组织一场有效的代码检查" tabindex="-1">怎么组织一场有效的代码检查 <a class="header-anchor" href="#怎么组织一场有效的代码检查" aria-label="Permalink to &quot;怎么组织一场有效的代码检查&quot;">​</a></h2><p>知道查什么之后，更重要的是<strong>怎么查才不变成走过场</strong>。</p><h3 id="角色分工" tabindex="-1">角色分工 <a class="header-anchor" href="#角色分工" aria-label="Permalink to &quot;角色分工&quot;">​</a></h3><p>一场正式的代码检查通常需要四个角色：</p><table tabindex="0"><thead><tr><th>角色</th><th>谁做</th><th>干嘛</th></tr></thead><tbody><tr><td><strong>主持人</strong></td><td>不是代码作者</td><td>控制节奏，确保检查聚焦在找错误上，不让会议变成&quot;辩解大会&quot;</td></tr><tr><td><strong>代码作者</strong></td><td>写这段代码的人</td><td>讲解代码，记录发现的问题，不参与&quot;辩论&quot;</td></tr><tr><td><strong>检查员</strong></td><td>2~3 名其他开发者</td><td>拿着错误清单逐项扫描，提问题</td></tr><tr><td><strong>记录员</strong></td><td>可以兼任</td><td>记录所有发现的问题，会后发给所有人</td></tr></tbody></table><p><strong>核心原则：主持人和检查员不要是代码作者。</strong> <a href="/testing/basics/what-is-testing.html">重新认识软件测试</a> 中有一条原则——自己写的代码，自己查不出来。</p><h3 id="流程" tabindex="-1">流程 <a class="header-anchor" href="#流程" aria-label="Permalink to &quot;流程&quot;">​</a></h3><ol><li><strong>会前准备</strong>（提前 1~2 天）：把代码和需求文档发给检查员，让他们提前看过</li><li><strong>开会时</strong>：作者逐段讲解代码逻辑（这是什么、为什么这样写），检查员对照清单提问</li><li><strong>记录问题</strong>：发现一个问题记一个，当场不讨论&quot;怎么改&quot;，只确认&quot;是不是问题&quot;</li><li><strong>会后跟踪</strong>：作者根据问题清单修复，修复后提交复查</li></ol><h3 id="最容易踩的-3-个坑" tabindex="-1">最容易踩的 3 个坑 <a class="header-anchor" href="#最容易踩的-3-个坑" aria-label="Permalink to &quot;最容易踩的 3 个坑&quot;">​</a></h3><ol><li><strong>陷入&quot;怎么改&quot;的讨论</strong> —— 检查的目的是找到错误，不是当场设计解决方案。一旦开始聊&quot;那改成这样行不行&quot;，时间就飞了</li><li><strong>变成代码风格 battle</strong> —— 空格 vs Tab、大括号换行不换行，检查就是找 bug，代码风格交给 lint 工具</li><li><strong>变成&quot;批判作者&quot;</strong> —— &quot;你怎么能犯这种低级错误&quot;——只要说出来，下一次这个人绝对不会再请你看代码。<strong>对事不对人</strong>，不是说说而已</li></ol><h3 id="时间和规模的两个硬约束" tabindex="-1">时间和规模的两个硬约束 <a class="header-anchor" href="#时间和规模的两个硬约束" aria-label="Permalink to &quot;时间和规模的两个硬约束&quot;">​</a></h3><p>有两个经验值值得记住，违反哪个效果都会打折扣：</p><ul><li><strong>单次检查不超过 90~120 分钟</strong>。超过两小时，注意力断崖式下降——后面的 bug 基本是在&quot;假装在看&quot;</li><li><strong>每小时的检查量控制在 150 行左右</strong>。看上去不多，但你真的逐行看懂、对照清单排查每个条目，150 行已经需要高度集中了。贪多塞一堆代码进议程，结果就是快速扫一眼——跟没查差不多</li></ul><p>如果代码量很大，<strong>拆成多场检查</strong>，每场聚焦一个模块。</p><h3 id="现代实践-人工检查-自动化门禁" tabindex="-1">现代实践：人工检查 + 自动化门禁 <a class="header-anchor" href="#现代实践-人工检查-自动化门禁" aria-label="Permalink to &quot;现代实践：人工检查 + 自动化门禁&quot;">​</a></h3><p>代码检查不只在开会时做。现代 CI/CD 流程中，人工检查的前后都有自动化工具配合：</p><ul><li><strong>提交前</strong>：lint（ESLint、Pylint）检查代码风格 → SAST（SonarQube、CodeQL）扫描安全漏洞 → 单元测试覆盖率门槛</li><li><strong>提交后</strong>：人工检查聚焦自动化工具<strong>做不到的事</strong>——业务逻辑是否正确、设计是否合理、有没有遗漏需求</li></ul><p>这套组合在<a href="/testing/methodology/security-testing.html">安全测试与渗透测试</a> 和 <a href="/testing/engineering/continuous-delivery-1.html">持续交付（上）</a>会详细展开。这里先有个印象：<strong>人工代码检查不是孤立的活动，它是质量门禁链条中的一环。</strong></p><h2 id="代码检查-vs-运行测试" tabindex="-1">代码检查 vs 运行测试 <a class="header-anchor" href="#代码检查-vs-运行测试" aria-label="Permalink to &quot;代码检查 vs 运行测试&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>代码检查</th><th>运行测试</th></tr></thead><tbody><tr><td>发现逻辑错误的效率</td><td>高</td><td>中</td></tr><tr><td>发现性能问题</td><td>几乎不能</td><td>能</td></tr><tr><td>发现&quot;缺少了什么&quot;</td><td>能（看源码发现某条需求没实现）</td><td>难（测试只能验证存在的东西）</td></tr><tr><td>对审查者的要求</td><td>需要经验和技能</td><td>门槛相对低</td></tr><tr><td>可自动化程度</td><td>低（最多 lint 协助）</td><td>高</td></tr></tbody></table><p>两者不是二选一，是<strong>互补</strong>。先用代码检查筛一遍逻辑错误和遗漏，再用运行测试验证执行结果和性能指标。顺序很重要——bug 被代码检查拦住，就不需要写 10 个测试用例去发现它了。</p><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ol><li>代码检查是<strong>成本最低的找错方式</strong>——在运行测试之前就能发现大量逻辑错误</li><li>有三种形式：检查（对照清单严格审查）、走查（作者逐行讲解）、评审（独立阅读），按风险等级选用</li><li><strong>七大错误类型</strong>是核心工具：数据引用、数据声明、运算、比较、控制流程、接口、I/O，每类都有具体的排查项</li><li>一场有效的代码检查需要<strong>角色分工</strong>（主持人 + 作者 + 检查员 + 记录员）加上<strong>时间和规模约束</strong>（单次 ≤ 2 小时、每小时约 150 行）</li><li><strong>对事不对人</strong>是底线——检查的目标是让代码更好，不是证明谁写错了</li><li>代码检查和运行测试是<strong>互补关系</strong>：检查发现逻辑遗漏，运行发现执行问题。现代实践中人工检查与 lint、SAST 等自动化工具形成组合拳</li></ol>',56)])])}const b=o(l,[["render",r]]);export{g as __pageData,b as default};
